<script setup lang="ts">import{onMounted}from'vue';import{RefreshCw,Search,ShieldX,Wrench}from'@lucide/vue';import StatusBadge from'../components/StatusBadge.vue';import{useInstrumentStore}from'../stores/instruments';const store=useInstrumentStore();onMounted(store.load)</script>
<template><section><div class="page-title"><div><h1>仪器台账</h1><p>查看计量状态、责任位置与下次校准日期</p></div><button class="primary"><Wrench :size="17"/>登记仪器</button></div><div class="metrics"><article><small>仪器总数</small><strong>{{store.total}}</strong><span>当前台账</span></article><article><small>禁用或异常</small><strong class="danger">{{store.blockedCount}}</strong><span>使用前将被拦截</span></article><article><small>本月到期</small><strong>{{store.instruments.filter(i=>i.status==='due_soon').length}}</strong><span>等待安排校准</span></article></div><div class="toolbar"><label class="search"><Search :size="17"/><input v-model="store.query" placeholder="搜索编号、名称或型号" @keyup.enter="store.load"></label><select v-model="store.status" @change="store.load"><option value="">全部状态</option><option value="qualified">合格</option><option value="due_soon">即将到期</option><option value="overdue">逾期</option><option value="unqualified">不合格</option><option value="disabled">禁用</option></select><button class="icon" title="刷新" @click="store.load"><RefreshCw :size="17"/></button></div><div v-if="store.error" class="notice error"><ShieldX :size="18"/>{{store.error}}</div><div class="table-wrap"><table><thead><tr><th>资产编号</th><th>仪器</th><th>型号</th><th>位置</th><th>关键等级</th><th>状态</th><th>下次校准</th></tr></thead><tbody><tr v-for="item in store.instruments" :key="item.id"><td class="mono">{{item.asset_number}}</td><td><strong>{{item.name}}</strong></td><td>{{item.model||'—'}}</td><td>{{item.location||'—'}}</td><td>{{item.criticality==='critical'?'关键':item.criticality==='major'?'重要':'普通'}}</td><td><StatusBadge :status="item.status"/></td><td>{{item.next_due_at?new Date(item.next_due_at).toLocaleDateString('zh-CN'):'待安排'}}</td></tr><tr v-if="!store.loading&&!store.instruments.length"><td colspan="7" class="empty">暂无符合条件的仪器</td></tr></tbody></table></div></section></template>

